actions.script:
def org=access.organizationPartyId
def discountSetting=ec.entity.find('moqui.security.UserPreference').condition('userId',org).condition('preferenceKey','POS_DISC_LIMIT').one()?.preferenceValue
def terminal=ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',terminalId).one()
def modes=offered.modes.collect { [id:it.salesModeId,name:it.modeName,inclusive:it.isTaxInclusive=='Y',disc:it.discountPercent ?: 0,source:it.priceSource] }
def rules=ec.entity.find('zenith.erp.pos.PosSalesModeOrgConfig').condition('organizationPartyId',org).list()
def productIds=catalog.products*.productId
def productRows=productIds ? ec.entity.find('mantle.product.Product').condition('productId','in',productIds).list().collectEntries { [(it.productId):it] } : [:]
def fixedPrices=productIds ? ec.entity.find('zenith.erp.pos.PosProductModePrice').condition('productId','in',productIds).list().collectEntries { [(it.productId+'\u0000'+it.salesModeId):it.price] } : [:]
def region=terminal.stateCode ?: terminal.regionGeoId ?: ec.entity.find('zenith.erp.india.IndiaGstConfig').condition('organizationPartyId',org).limit(1).one()?.stateCode
def other=region ? ec.entity.find('zenith.erp.india.IndiaState').condition('stateCode','not-equals',region).limit(1).one()?.stateCode : null
def interstate=other && productIds ? ec.service.sync().name('zenith.tax.TaxServices.calculate#Tax').parameters([organizationPartyId:org,
    items:productIds.collect { id -> def p=productRows[id];[productId:id,productTaxCode:p.productTaxCode,taxCategoryId:p.taxCategoryId,quantity:1,unitAmount:100,isTaxInclusive:'N'] },
    originRegionGeoId:region,destinationRegionGeoId:other,transactionType:'SALE']).call() : null
def products=catalog.products.collect { product ->
    def p=productRows[product.productId]
    def prices=[:]
    modes.each { mode ->
        def fixed=mode.source=='PpsFixedProduct'
        def price=fixed ? fixedPrices[p.productId+'\u0000'+mode.id] : (p.mrpAmount ?: 0)
        prices[mode.id]=[price:price ?: 0,disc:mode.source in ['PpsDiscountMrp','PpsDiscountList'] ? mode.disc : 0,blocked:fixed && (price==null || price<=0)]
    }
    def index=productIds.indexOf(p.productId)
    product+[printName:p.printName ?: p.productName,prices:prices,
        interstateRates:interstate?.taxedItems ? (interstate.taxedItems[index].taxBreakdowns?.collect { it.taxRate ?: 0 } ?: []) : null]
}
def customerIds=ec.entity.find('mantle.party.Party').condition('ownerPartyId',org).list()*.partyId
def customers=[]
if (customerIds) ec.entity.find('mantle.party.PartyRole').condition('partyId','in',customerIds).condition('roleTypeId','Customer').list().each { role ->
    def detail=ec.entity.find('mantle.party.PartyDetailAndRole').condition('partyId',role.partyId).limit(1).list()
    def person=detail ? detail[0] : null
    def name=person?.organizationName ?: [person?.firstName,person?.lastName].findAll { it }.join(' ')
    def party=ec.entity.find('mantle.party.Party').condition('partyId',role.partyId).one()
    def phone='', state=''
    ec.entity.find('mantle.party.contact.PartyContactMech').condition('partyId',role.partyId).conditionDate('fromDate','thruDate',ec.user.nowTimestamp).list().each { link ->
        def tel=ec.entity.find('mantle.party.contact.TelecomNumber').condition('contactMechId',link.contactMechId).one()
        if (!phone && tel) phone=[tel.countryCode,tel.areaCode,tel.contactNumber].findAll { it }.join('')
        def address=ec.entity.find('mantle.party.contact.PostalAddress').condition('contactMechId',link.contactMechId).one()
        if (!state && address) state=address.stateProvinceGeoId ?: ''
    }
    def registration=ec.service.sync().name('zenith.tax.TaxServices.get#PartyTaxRegistration').parameter('partyId',role.partyId).call()
    if (name) customers.add([partyId:role.partyId,name:name,phone:phone,creditDays:party.creditDays,state:registration?.regionGeoId ?: '',gstin:registration?.registrationNumber ?: ''])
}
def templates=ec.entity.find('zenith.erp.pos.PosReceiptTemplate').condition('organizationPartyId',org).condition('isActive','Y').orderBy('-isDefault,templateId').list()
def template=templates.find { it.facilityId==terminal.facilityId } ?: templates.find { !it.facilityId }
workspace=[version:2,userId:ec.user.userId,organizationPartyId:org,terminalId:terminalId,cachedAt:ec.user.nowTimestamp.time,
    products:products,customers:customers,modes:modes,canOverride:priceAccess.canOverride==true,
    rules:rules.collect { [mode:it.salesModeId,customer:it.requireCustomer=='Y',minimum:it.minOrderAmount ?: 0] },
    discountLimit:discountSetting?.trim() ? new BigDecimal(discountSetting) : null,
    state:terminal.stateCode ?: terminal.regionGeoId ?: ec.entity.find('zenith.erp.india.IndiaGstConfig').condition('organizationPartyId',org).limit(1).one()?.stateCode,
    store:[name:template?.companyName ?: terminal.terminalName,taxReg:template?.taxRegistrationNumber ?: terminal.taxRegistrationNumber ?: '',
        address:template ? [template.addressLine1,template.addressLine2,template.city,template.state,template.pincode].findAll { it }.join(', ') : '',phone:template?.phone ?: '']]

def org=access.organizationPartyId
def fail={ String message -> throw new IllegalArgumentException(message) }
if (sale.version!=2 || !sale.offlineId || sale.offlineId.toString().size()>120 || sale.terminalId!=terminalId || sale.organizationPartyId!=org || sale.userId!=ec.user.userId || !(sale.items instanceof List) || !sale.items || sale.items.size()>1000 || !(sale.taxOn in ['Y','N'])) fail('Invalid offline sale identity or items.')
def issued=java.sql.Timestamp.from(java.time.Instant.parse(sale.ts as String))
if (issued.time>ec.user.nowTimestamp.time+300000L) fail('The terminal clock is ahead. Keep this sale for review.')
ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',terminalId).forUpdate(true).one()
def key=java.util.UUID.nameUUIDFromBytes((org+'\u0000'+sale.offlineId).getBytes('UTF-8')).toString()
def prior=ec.entity.find('zenith.erp.pos.PosOfflineTransaction').condition('offlineTransactionId',key).one()
if (prior?.statusId=='OtSynced') { offlineId=sale.offlineId; return }
def session=ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',sale.sessionId).condition('organizationPartyId',org).condition('terminalId',terminalId).condition('statusId','PsOpen').one()
if (!session) fail('The original terminal session is closed. Keep this sale on the device for reconciliation.')
def transactionId
if (sale.sourceTransactionId) {
    def permission=ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').parameters([transactionId:sale.sourceTransactionId]).call()
    if (!permission?.allowed) return
    def source=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',sale.sourceTransactionId).forUpdate(true).one()
    def revision=ec.service.sync().name('zenith.pos.PosOfflineServices.get#DraftRevision').parameter('transactionId',source.transactionId).call().revision
    if (source.sessionId!=session.sessionId || source.statusId!='PtCreated' || (source.paidAmount ?: 0)!=0 || !sale.sourceRevision || sale.sourceRevision!=revision ||
        ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',source.transactionId).count()>0 ||
        ec.entity.find('zenith.erp.pos.PosQrPayment').condition('transactionId',source.transactionId).count()>0) fail('The original draft changed or has a tender in progress. Keep this offline sale for review; it was not imported twice.')
    transactionId=source.transactionId
    ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',transactionId).list().each { item ->
        ec.service.sync().name('zenith.pos.PosServices.remove#PosTransactionItem').parameters([transactionId:transactionId,itemSeqId:item.itemSeqId]).call()
    }
} else transactionId=ec.service.sync().name('zenith.pos.PosServices.create#PosTransaction').parameters([sessionId:session.sessionId,reuseOpenCart:false]).call().transactionId
def txn=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).one()
def registration=sale.customer?.partyId ? ec.service.sync().name('zenith.tax.TaxServices.get#PartyTaxRegistration').parameter('partyId',sale.customer.partyId).call() : null
def canonical=sale.customer?.partyId ? ec.entity.find('mantle.party.PartyDetailAndRole').condition('partyId',sale.customer.partyId).limit(1).list() : []
def customerName=canonical ? (canonical[0].organizationName ?: [canonical[0].firstName,canonical[0].lastName].findAll { it }.join(' ')) : sale.customer?.name
txn.setAll([customerPartyId:sale.customer?.partyId,customerName:customerName,customerPhone:sale.customer?.phone,salesModeId:sale.mode ?: null,
    customerTaxRegNumber:registration?.registrationNumber,destinationRegionGeoId:registration?.regionGeoId ?: txn.originRegionGeoId])
txn.update()
def priceAccess=ec.service.sync().name('zenith.pos.PosPriceServices.get#PriceOverrideAccess').call()
def discountSetting=ec.entity.find('moqui.security.UserPreference').condition('userId',org).condition('preferenceKey','POS_DISC_LIMIT').one()?.preferenceValue
def discountLimit=discountSetting?.trim() ? new BigDecimal(discountSetting) : null
sale.items.each { item ->
    if (!(item instanceof Map) || item.qty==null || item.price==null || (item.qty as BigDecimal)<=0 || (item.price as BigDecimal)<=0) fail('Positive prices and quantities are required offline; free items need online manager approval.')
    ec.service.sync().name('zenith.pos.PosModeServices.assert#TerminalMode').parameters([terminalId:terminalId,salesModeId:item.mode]).call()
    def resolved=ec.service.sync().name('zenith.pos.PosServices.resolve#PosModePrice').parameters([productId:item.productId,salesModeId:item.mode]).call()
    if (!priceAccess.canOverride && (resolved.blocked || (resolved.unitPrice as BigDecimal).compareTo(item.price as BigDecimal)!=0)) fail('POS write permission is required for this offline price override.')
    def percent=(item.discount ?: 0) as BigDecimal
    if (percent<0 || percent>100 || (percent!=(resolved.discountPercent ?: 0) && discountLimit!=null && percent>discountLimit)) fail('This discount needs online manager approval.')
    def added=ec.service.sync().name('zenith.pos.PosServices.add#PosTransactionItem').parameters([transactionId:transactionId,productId:item.productId,quantity:item.qty,unitPrice:item.price,salesModeId:item.mode,taxOn:sale.taxOn]).call()
    if (added?.itemSeqId) {
        def recorded=ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',transactionId).condition('itemSeqId',added.itemSeqId).one()
        // The normal add path treats an MRP-valued input as a default mode price.
        // Restore an explicitly captured offline override through the audited permission check.
        if ((recorded.unitPrice as BigDecimal).compareTo(item.price as BigDecimal)!=0)
            ec.service.sync().name('zenith.pos.PosPriceServices.set#ItemPrice').parameters([transactionId:transactionId,itemSeqId:added.itemSeqId,newPrice:item.price,taxOn:sale.taxOn]).call()
    }
    if (added?.itemSeqId && percent!=(resolved.discountPercent ?: 0)) ec.service.sync().name('update#zenith.erp.pos.PosTransactionItem').parameters([transactionId:transactionId,itemSeqId:added.itemSeqId,discountPercent:percent,discountAmount:(item.price as BigDecimal)*(item.qty as BigDecimal)*percent/100]).call()
}
if (ec.message.hasError()) return
ec.service.sync().name('zenith.pos.PosServices.refresh#PosTransactionTax').parameters([transactionId:transactionId,taxOn:sale.taxOn]).call()
txn=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).one()
if (sale.total==null || (sale.total as BigDecimal).compareTo(txn.payableAmount as BigDecimal)!=0 || sale.taxAmount==null || (sale.taxAmount as BigDecimal).compareTo(txn.totalTaxAmount as BigDecimal)!=0) fail('Offline tax or total differs from current rules. Sale retained for review, without changing its collected amount.')
if (sale.paymentMethod=='Credit') {
    if (!sale.customer?.name || !sale.customer?.phone) fail('Credit requires a customer name and phone.')
    ec.service.sync().name('zenith.pos.PosServices.complete#PosTransactionCredit').parameters([transactionId:transactionId,customerPartyId:sale.customer.partyId,customerName:sale.customer.name,customerPhone:sale.customer.phone,creditDays:sale.customer.creditDays]).call()
    if (!ec.message.hasError()) {
        def credit=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).one()
        if (credit.creditDays!=null) {credit.creditDueDate=java.sql.Date.valueOf(issued.toInstant().atZone(ec.user.timeZone.toZoneId()).toLocalDate().plusDays(credit.creditDays as long));credit.update()}
    }
} else {
    if (!(sale.payments instanceof List) || !sale.payments || sale.payments.size()>3) fail('Enter a valid payment breakdown.')
    def paid=0G
    sale.payments.each { payment ->
        if (!(payment.method in ['Cash','Card','UPI']) || payment.amount==null || (payment.amount as BigDecimal)<=0 || (payment.amount as BigDecimal).scale()>2) fail('Invalid offline payment.')
        paid+=payment.amount as BigDecimal
    }
    def change=(sale.change ?: 0) as BigDecimal
    if (change<0 || (paid-change).compareTo(txn.payableAmount as BigDecimal)!=0 ||
        (change>0 && (sale.paymentMethod!='Cash' || sale.payments.size()!=1 || sale.payments[0].method!='Cash'))) fail('Payment breakdown or change does not match the sale.')
    sale.payments.each { payment -> ec.service.sync().name('zenith.pos.PosServices.process#PosPayment').parameters([transactionId:transactionId,paymentMethod:payment.method,amount:payment.amount,referenceNumber:'OFFLINE:'+sale.offlineId]).call() }
    ec.service.sync().name('zenith.pos.PosServices.complete#PosTransaction').parameters([transactionId:transactionId]).call()
}
if (ec.message.hasError()) return
ec.service.sync().name('create#zenith.erp.pos.PosOfflineTransaction').parameters([offlineTransactionId:key,terminalId:terminalId,offlineTimestamp:issued,syncedTimestamp:ec.user.nowTimestamp,transactionDataJson:groovy.json.JsonOutput.toJson(sale),itemCount:sale.items.size(),grandTotal:sale.total,paymentMethod:sale.paymentMethod,statusId:'OtSynced',syncAttempts:1,createdTransactionId:transactionId]).call()
if (!ec.message.hasError()) offlineId=sale.offlineId
